                ret.ENLT = this.ENLT.Combine(rhs.ENLT);
                ret.ENLS = this.ENLS.Combine(rhs.ENLS);
                ret.AUUV = this.AUUV.Combine(rhs.AUUV);
                ret.TextureSet = this.TextureSet.Combine(rhs.TextureSet);
