        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IHeadPartGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            foreach (var item in obj.ExtraParts)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.HNAM2, out var HNAM2Info))
            {
                yield return HNAM2Info;
            }
            if (FormLinkInformation.TryFactory(obj.TextureSet, out var TextureSetInfo))
            {
                yield return TextureSetInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Color, out var ColorInfo))
            {
                yield return ColorInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ValidRace, out var ValidRaceInfo))
            {
                yield return ValidRaceInfo;
            }
            if (FormLinkInformation.TryFactory(obj.NAM0, out var NAM0Info))
            {
                yield return NAM0Info;
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            yield break;
        }
        
