        public static IHeadPartGetter HeadPartFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new HeadPartBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static IHeadPartGetter HeadPartFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return HeadPartFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)HeadPart_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)HeadPart_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.XALG:
                {
                    _XALGLocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.XALG;
                }
                case RecordTypeInts.FULL:
                {
                    _FULLLocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.FULL;
                }
                case RecordTypeInts.MODL:
                case RecordTypeInts.MODC:
                case RecordTypeInts.MODT:
                case RecordTypeInts.MODS:
                {
                    this.Model = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)HeadPart_FieldIndex.Model;
                }
                case RecordTypeInts.DATA:
                {
                    _DATALocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.DATA;
                }
                case RecordTypeInts.PNAM:
                {
                    _PartTypeLocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.PartType;
                }
                case RecordTypeInts.HNAM:
                {
                    if (!lastParsed.ParsedIndex.HasValue
                        || lastParsed.ParsedIndex.Value <= (int)HeadPart_FieldIndex.PartType)
                    {
                        this.ExtraParts = BinaryOverlayList.FactoryByArray<IFormLinkGetter<IHeadPartGetter>>(
                            mem: stream.RemainingMemory,
                            package: _package,
                            getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<IHeadPartGetter>(p, s),
                            locs: ParseRecordLocations(
                                stream: stream,
                                constants: _package.MetaData.Constants.SubConstants,
                                trigger: RecordTypes.HNAM,
                                skipHeader: true,
                                translationParams: translationParams));
                        return new ParseResult((int)HeadPart_FieldIndex.ExtraParts, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)HeadPart_FieldIndex.ExtraParts)
                    {
                        _HNAM2Location = (stream.Position - offset);
                        return new ParseResult((int)HeadPart_FieldIndex.HNAM2, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                this.ExtraParts = BinaryOverlayList.FactoryByArray<IFormLinkGetter<IHeadPartGetter>>(
                                    mem: stream.RemainingMemory,
                                    package: _package,
                                    getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<IHeadPartGetter>(p, s),
                                    locs: ParseRecordLocations(
                                        stream: stream,
                                        constants: _package.MetaData.Constants.SubConstants,
                                        trigger: RecordTypes.HNAM,
                                        skipHeader: true,
                                        translationParams: translationParams));
                                return new ParseResult((int)HeadPart_FieldIndex.ExtraParts, type);
                            }
                            case 1:
                            {
                                _HNAM2Location = (stream.Position - offset);
                                return new ParseResult((int)HeadPart_FieldIndex.HNAM2, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.ENLT:
                {
                    _ENLTLocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.ENLT;
                }
                case RecordTypeInts.ENLS:
                {
                    _ENLSLocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.ENLS;
                }
                case RecordTypeInts.AUUV:
                {
                    _AUUVLocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.AUUV;
                }
                case RecordTypeInts.TNAM:
                {
                    _TextureSetLocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.TextureSet;
                }
                case RecordTypeInts.CNAM:
                {
                    _ColorLocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.Color;
                }
                case RecordTypeInts.RNAM:
                {
                    _ValidRaceLocation = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.ValidRace;
                }
                case RecordTypeInts.NAM0:
                {
                    _NAM0Location = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.NAM0;
                }
                case RecordTypeInts.NAM1:
                {
                    _NAM1Location = (stream.Position - offset);
                    return (int)HeadPart_FieldIndex.NAM1;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    this.Conditions = BinaryOverlayList.FactoryByCountPerItem<IConditionGetter>(
                        stream: stream,
                        package: _package,
                        countLength: 4,
                        trigger: Condition_Registration.TriggerSpecs,
                        countType: RecordTypes.CITC,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ConditionBinaryOverlay.ConditionFactory(new OverlayStream(s, p), p, recConv),
                        skipHeader: false);
                    return (int)HeadPart_FieldIndex.Conditions;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
